style.css:
/* Apply pastel colors to the whole page */
* {
  background-color: #B2EBF2; /* Pastel light cyan background */
  color: #D1007F; /* Soft magenta text */
  font-family: Arial, sans-serif; /* Proper semicolon */
} /* Apply background image for Roblox site */
@-moz-document domain("roblox.com") {
* {
    background-image: url('https://www.pinterest.com/pin/74027987620595313/') !important;
    background-size: cover !important; /* Ensures the image covers the entire background */
    background-position: center center !important;
    background-repeat: no-repeat !important;
  }
}
